import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788283385000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>HEALTHCHECKS_API_KEY</code></td><td>yes</td><td>—</td><td>Project API key, exactly 32 characters. Read-only or read-write</td></tr><tr><td><code>HEALTHCHECKS_URL</code></td><td>no</td><td><code>https://healthchecks.io</code></td><td>Site root of a self-hosted instance. A trailing <code>/api/vN</code> is trimmed</td></tr><tr><td><code>HEALTHCHECKS_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>HEALTHCHECKS_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>HEALTHCHECKS_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>HEALTHCHECKS_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to this connection</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>The <code>HEALTHCHECKS_*</code> booleans are the exact string <code>true</code>; anything else, including <code>1</code> and <code>TRUE</code>, is false. <code>ELICITATION</code> is the exception in both directions — see below.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before <code>delete_check</code> acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> <code>1</code>, <code>off</code> or a typo stop the server with exit code 1 rather than falling back to the default. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>HEALTHCHECKS_API_KEY</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the key sitting there for a crash reporter.</p><h2 id="healthchecks-api-key" tabindex="-1"><code>HEALTHCHECKS_API_KEY</code> <a class="header-anchor" href="#healthchecks-api-key" aria-label="Permalink to “HEALTHCHECKS_API_KEY”">​</a></h2><p>Per <strong>project</strong>, not per account — Project Settings → API Access. Exactly 32 characters; the upstream answers any other length with <code>401 missing api key</code>, which looks like a header that never arrived, so the server checks the length itself at startup and before each call.</p><p>Read from the environment once and then deleted from <code>process.env</code>, so it is not visible to child processes. It is sent as <code>X-Api-Key</code> and never in a request body.</p><p>A read-only key (<code>hcr_…</code> on the hosted service) reaches <code>list_checks</code>, <code>get_check</code>, <code>list_flips</code> and <code>list_badges</code>. It does not reach <code>list_pings</code>, <code>get_ping_body</code>, <code>list_integrations</code> or any write tool. See <a href="/guide/configuration#read-only-and-read-write-keys">read-only and read-write keys</a>.</p><h2 id="healthchecks-url" tabindex="-1"><code>HEALTHCHECKS_URL</code> <a class="header-anchor" href="#healthchecks-url" aria-label="Permalink to “HEALTHCHECKS_URL”">​</a></h2><p>The site root of a self-hosted instance: <code>https://hc.example.net</code>. Must be <code>http:</code> or <code>https:</code> and must not carry <code>user:pass@</code> credentials — both are fatal at startup, because a malformed target is the one misconfiguration that can send the key to the wrong host. Plain <code>http</code> to a non-loopback host warns and continues.</p><p>A value ending in <code>/api/v1</code>, <code>/api/v2</code> or <code>/api/v3</code> is trimmed back to the site root, so a URL copied out of the API documentation works as well as the short one.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><p>The syntax, exactly; for why you would want it, see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p><code>HEALTHCHECKS_ALLOW_TOOLS</code> and <code>HEALTHCHECKS_DENY_TOOLS</code> are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated preset, marked in the <a href="/reference/tools">tool reference</a></td></tr><tr><td><code>list_*,get_check</code></td><td>exactly those</td></tr><tr><td><code>list_*</code></td><td>every tool whose name starts with <code>list_</code></td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>HEALTHCHECKS_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_check</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>HEALTHCHECKS_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};